// src/embed-cache.ts
function contentHash(text) {
  return createHash("sha256").update(text, "utf-8").digest("hex");
}

class CachedEmbeddingProvider {
  name;
  dimensions;
  modelName;
  inner;
  tiers;
  memoryCacheSize;
  memoryCache;
  sqliteDbPath;
  solrClient;
  db;
  dbInitFailed;
  stats;
  constructor(options2) {
    this.inner = options2.inner;
    this.name = `cached(${options2.inner.name})`;
    this.modelName = modelIdentity(options2.inner);
    this.dimensions = options2.inner.dimensions;
    this.tiers = options2.tiers;
    this.memoryCacheSize = options2.memoryCacheSize;
    this.memoryCache = new Map;
    this.sqliteDbPath = options2.sqliteDbPath;
    this.solrClient = options2.solrClient;
    this.db = null;
    this.dbInitFailed = false;
    this.stats = {
      memory: { hits: 0, misses: 0, size: 0 },
      sqlite: { hits: 0, misses: 0, size: 0 },
      solr: { hits: 0, misses: 0 }
    };
  }
  cacheKey(text) {
    return createHash("sha256").update(`${this.modelName}:${this.dimensions}\x00${text}`, "utf-8").digest("hex");
  }
  async embed(text) {
    const hash2 = this.cacheKey(text);
    for (const tier of this.tiers) {
      const cached2 = await this.getFromTier(tier, hash2, contentHash(text));
      if (cached2) {
        return cached2;
      }
    }
    const embedding = await this.inner.embed(text);
    this.writeToMemory(hash2, embedding);
    this.writeToSqlite(hash2, embedding);
    return embedding;
  }
  async batchEmbed(texts) {
    const results = new Array(texts.length).fill(null);
    const missIndices = [];
    const missTexts = [];
    for (let i = 0;i < texts.length; i++) {
      const hash2 = this.cacheKey(texts[i]);
      let found = false;
      for (const tier of this.tiers) {
        const cached2 = await this.getFromTier(tier, hash2, contentHash(texts[i]));
        if (cached2) {
          results[i] = cached2;
          found = true;
          break;
        }
      }
      if (!found) {
        missIndices.push(i);
        missTexts.push(texts[i]);
      }
    }
    if (missTexts.length > 0) {
      const embeddings = await this.inner.batchEmbed(missTexts);
      for (let j = 0;j < missIndices.length; j++) {
        const idx = missIndices[j];
        results[idx] = embeddings[j];
        const hash2 = this.cacheKey(missTexts[j]);
        this.writeToMemory(hash2, embeddings[j]);
        this.writeToSqlite(hash2, embeddings[j]);
      }
    }
    return results;
  }
  getStats() {
    return {
      memory: { ...this.stats.memory, size: this.memoryCache.size },
      sqlite: { ...this.stats.sqlite, size: this.getSqliteSize() },
      solr: { ...this.stats.solr }
    };
  }
  async getFromTier(tier, key, contentKey) {
    switch (tier) {
      case "memory":
        return this.getFromMemory(key);
      case "sqlite":
        return this.getFromSqlite(key);
      case "solr":
        return this.getFromSolr(contentKey);
    }
  }
  getFromMemory(hash2) {
    const entry = this.memoryCache.get(hash2);
    if (entry) {
      this.memoryCache.delete(hash2);
      this.memoryCache.set(hash2, entry);
      this.stats.memory.hits++;
      return entry;
    }
    this.stats.memory.misses++;
    return null;
  }
  writeToMemory(hash2, embedding) {
    if (!this.tiers.includes("memory"))
      return;
    if (this.memoryCache.size >= this.memoryCacheSize && !this.memoryCache.has(hash2)) {
      const firstKey = this.memoryCache.keys().next().value;
      if (firstKey !== undefined) {
        this.memoryCache.delete(firstKey);
      }
    }
    this.memoryCache.set(hash2, embedding);
  }
  ensureSqliteDb() {
    if (this.db)
      return true;
    if (this.dbInitFailed)
      return false;
    try {
      const { Database } = __require("bun:sqlite");
      mkdirSync(dirname(this.sqliteDbPath), { recursive: true });
      this.db = new Database(this.sqliteDbPath);
      this.db.exec(`
        CREATE TABLE IF NOT EXISTS embeddings (
          content_hash  TEXT PRIMARY KEY,
          embedding     BLOB NOT NULL,
          provider_name TEXT NOT NULL,
          dimensions    INTEGER NOT NULL,
          created_at    TEXT NOT NULL DEFAULT (datetime('now'))
        );
      `);
      return true;
    } catch (err) {
      console.error(`[souk-compass] SQLite cache init failed: ${err instanceof Error ? err.message : String(err)}`);
      this.dbInitFailed = true;
      return false;
    }
  }
  getFromSqlite(hash2) {
    if (!this.ensureSqliteDb()) {
      this.stats.sqlite.misses++;
      return null;
    }
    try {
      const row = this.db.query("SELECT embedding FROM embeddings WHERE content_hash = ?").get(hash2);
      if (row) {
        const raw = new TextDecoder().decode(row.embedding);
        const embedding = JSON.parse(raw);
        this.stats.sqlite.hits++;
        return embedding;
      }
    } catch (err) {
      console.error(`[souk-compass] SQLite cache read error: ${err instanceof Error ? err.message : String(err)}`);
    }
    this.stats.sqlite.misses++;
    return null;
  }
  writeToSqlite(hash2, embedding) {
    if (!this.tiers.includes("sqlite"))
      return;
    if (!this.ensureSqliteDb())
      return;
    try {
      this.db.query(`INSERT OR REPLACE INTO embeddings (content_hash, embedding, provider_name, dimensions, created_at)
         VALUES (?, ?, ?, ?, datetime('now'))`).run(hash2, Buffer.from(JSON.stringify(embedding)), this.inner.name, this.dimensions);
    } catch (err) {
      console.error(`[souk-compass] SQLite cache write error: ${err instanceof Error ? err.message : String(err)}`);
    }
  }
  getSqliteSize() {
    if (!this.db)
      return 0;
    try {
      const row = this.db.query("SELECT COUNT(*) as count FROM embeddings").get();
      return row?.count ?? 0;
    } catch {
      return 0;
    }
  }
  async getFromSolr(hash2) {
    if (!this.solrClient) {
      this.stats.solr.misses++;
      return null;
    }
    try {
      const doc2 = await this.solrClient.findByContentHash(hash2, this.modelName);
      if (doc2?.vector) {
        this.stats.solr.hits++;
        return doc2.vector;
      }
    } catch {}
    this.stats.solr.misses++;
    return null;
  }
}

