// src/tools/compass-health.ts
async function handleCompassHealth(_input, ctx) {
  const solrReachable = await ctx.solrClient.health();
  const collections = [];
  for (const { name } of [
    { name: ctx.config.solrCollection },
    { name: ctx.config.userCollection }
  ]) {
    if (solrReachable) {
      const exists = await checkCollectionExists(ctx.config.solrUrl, name);
      collections.push({ name, exists });
    } else {
      collections.push({ name, exists: false });
    }
  }
  return {
    content: [
      {
        type: "text",
        text: JSON.stringify({ solrReachable, collections }, null, 2)
      }
    ]
  };
}
async function checkCollectionExists(solrUrl, collectionName) {
  try {
    const url2 = `${solrUrl}/solr/${encodeURIComponent(collectionName)}/select?q=*:*&rows=0&wt=json`;
    const response = await fetch(url2);
    return response.ok;
  } catch {
    return false;
  }
}

