// src/catalog-reader.ts
async function loadCatalog(pluginRoot) {
  const catalogPath = join2(pluginRoot, "kanon", "catalog.json");
  const raw = await readFile(catalogPath, "utf-8");
  const parsed = JSON.parse(raw);
  return CatalogSchema.parse(parsed);
}
async function readArtifactContent(pluginRoot, entry) {
  const relativePath = entry.path ?? join2("knowledge", entry.name);
  const filePath = join2(pluginRoot, "kanon", relativePath, "knowledge.md");
  const raw = await readFile(filePath, "utf-8");
  const parsed = import_gray_matter.default(raw);
  return { frontmatter: parsed.data, body: parsed.content };
}

// src/chunker.ts
var DEFAULT_MAX_CHUNK_LENGTH = 8000;
function chunkMarkdown(body, options2) {
  const minLength = options2?.minLength ?? 50;
  const maxLength = options2?.maxLength ?? DEFAULT_MAX_CHUNK_LENGTH;
  const sections = body.split(/(?=^#{2,3}\s)/m);
  const merged = [];
  for (const section of sections) {
    if (merged.length > 0 && merged[merged.length - 1].length < minLength) {
      merged[merged.length - 1] += section;
    } else {
      merged.push(section);
    }
  }
  const packed = options2?.pack ? packSections(merged, maxLength) : merged;
  const final = [];
  for (const chunk of packed) {
    if (chunk.length > maxLength) {
      const paragraphs = chunk.split(/\n\n/);
      let current = "";
      for (const para of paragraphs) {
        if (current.length + para.length > maxLength && current.length > 0) {
          final.push(current);
          current = para;
        } else {
          current += (current ? `

` : "") + para;
        }
      }
      if (current)
        final.push(current);
    } else {
      final.push(chunk);
    }
  }
  return final.map((text, index) => ({ index, text }));
}
function packSections(sections, limit) {
  const out = [];
  let current = "";
  for (const section of sections) {
    if (current && current.length + section.length > limit) {
      out.push(current);
      current = section;
    } else {
      current += section;
    }
  }
  if (current)
    out.push(current);
  return out;
}
function buildChunkDocuments(artifactName, chunks, embeddings, metadata, embedProvider) {
  return chunks.map((chunk, i) => ({
    id: `${artifactName}__chunk_${chunk.index}`,
    text: chunk.text,
    vector: embeddings[i],
    chunk_index: chunk.index,
    parent_artifact: artifactName,
    doc_source: "artifact",
    ...metadata,
    ...embedProvider ? { embed_provider: embedProvider } : {}
  }));
}

