// src/codebase-docs.ts
import { createHash as createHash2 } from "node:crypto";
import { basename } from "node:path";
function rootKey(absoluteRoot) {
  const slug = basename(absoluteRoot).toLowerCase().replace(/[^a-z0-9._-]+/g, "-").replace(/^-+|-+$/g, "") || "root";
  const digest = createHash2("sha256").update(absoluteRoot, "utf-8").digest("hex").slice(0, 8);
  return `${slug}-${digest}`;
}
function chunkCode(content, maxLength) {
  if (content.length <= maxLength) {
    return [
      {
        index: 0,
        text: content,
        startLine: 1,
        endLine: content.split(`
`).length
      }
    ];
  }
  const lines = content.split(`
`);
  const chunks = [];
  let currentChunk = "";
  let chunkStartLine = 1;
  let lineIndex = 0;
  for (const line of lines) {
    lineIndex++;
    const wouldExceed = `${currentChunk}
${line}`.length > maxLength;
    if (wouldExceed && currentChunk.length > 0) {
      chunks.push({
        index: chunks.length,
        text: currentChunk,
        startLine: chunkStartLine,
        endLine: lineIndex - 1
      });
      currentChunk = line;
      chunkStartLine = lineIndex;
    } else {
      currentChunk = currentChunk ? `${currentChunk}
${line}` : line;
    }
  }
  if (currentChunk.length > 0) {
    chunks.push({
      index: chunks.length,
      text: currentChunk,
      startLine: chunkStartLine,
      endLine: lineIndex
    });
  }
  return chunks;
}
function buildCodebaseDocs(options2) {
  const { root, relativePath, content, chunkMaxLength, chunked } = options2;
  const key = rootKey(root);
  const base = `codebase::${key}::${relativePath}`;
  const chunks = chunked ? chunkCode(content, chunkMaxLength) : [
    {
      index: 0,
      text: content,
      startLine: 1,
      endLine: content.split(`
`).length
    }
  ];
  if (chunks.length === 1) {
    return [
      {
        id: base,
        text: `File: ${relativePath}

${chunks[0].text}`,
        relativePath
      }
    ];
  }
  return chunks.map((chunk) => ({
    id: `${base}::chunk_${chunk.index}`,
    text: `File: ${relativePath} (lines ${chunk.startLine}-${chunk.endLine})

${chunk.text}`,
    relativePath
  }));
}

