init_errors();
var CONFIG_NAME = "souk-compass";
async function getCollectionInfo(solrUrl, name) {
  try {
    const url3 = `${solrUrl}/solr/${encodeURIComponent(name)}/select?q=*:*&rows=0&wt=json`;
    const response = await fetch(url3);
    if (!response.ok)
      return { name, exists: false, docCount: null };
    const body = await response.json();
    return { name, exists: true, docCount: body.response?.numFound ?? 0 };
  } catch {
    return { name, exists: false, docCount: null };
  }
}
async function createCollection(solrUrl, name) {
  try {
    const url3 = `${solrUrl}/solr/admin/collections?action=CREATE&name=${encodeURIComponent(name)}&numShards=1&replicationFactor=1&collection.configName=${CONFIG_NAME}&wt=json`;
    const response = await fetch(url3);
    if (response.ok)
      return { name, created: true };
    const body = await response.text();
    return {
      name,
      created: false,
      error: body.includes("already exists") ? "Collection already exists" : `HTTP ${response.status}: ${body}`
    };
  } catch (err) {
    return {
      name,
      created: false,
      error: err instanceof Error ? err.message : String(err)
    };
  }
}
async function requireCollection(solrUrl, name) {
  const info = await getCollectionInfo(solrUrl, name);
  if (info.exists)
    return;
  throw new SoukCompassError(`Collection "${name}" does not exist. Create it with: ` + `compass_setup({ action: "create_collection", name: "${name}" }) — ` + `or omit the "collection" argument to use the configured default.`, ErrorCodes.CONFIG_INVALID);
}

