function errorResult(message) {
  return {
    isError: true,
    content: [{ type: "text", text: message }]
  };
}
async function main() {
  const { toolContext } = await bootstrap();
  server.setRequestHandler(CallToolRequestSchema, async (request) => {
    const args = request.params.arguments ?? {};
    try {
      let result;
      switch (request.params.name) {
        case "compass_setup":
          result = await handleCompassSetup(args, toolContext);
          break;
        case "compass_index_artifacts":
          result = await handleCompassIndexArtifacts(args, toolContext);
          break;
        case "compass_search":
          result = await handleCompassSearch(args, toolContext);
          break;
        case "compass_index_document":
          result = await handleCompassIndexDocument(args, toolContext);
          break;
        case "compass_status":
          result = await handleCompassStatus(args, toolContext);
          break;
        case "compass_health":
          result = await handleCompassHealth(args, toolContext);
          break;
        case "compass_reindex":
          result = await handleCompassReindex(args, toolContext);
          break;
        case "compass_recall":
          result = await handleCompassRecall(args, toolContext);
          break;
        case "compass_remember":
          result = await handleCompassRemember(args, toolContext);
          break;
        case "compass_recall_memory":
          result = await handleCompassRecallMemory(args, toolContext);
          break;
        case "compass_profile_workspace":
          result = await handleCompassProfileWorkspace(args, toolContext);
          break;
        case "compass_index_folder":
          result = await handleCompassIndexFolder(args, toolContext);
          break;
        case "compass_search_codebase":
          result = await handleCompassSearchCodebase(args, toolContext);
          break;
        case "compass_reindex_folder":
          result = await handleCompassReindexFolder(args, toolContext);
          break;
        default:
          result = errorResult(`Unknown tool: ${request.params.name}`);
      }
      return { ...result };
    } catch (err) {
      if (err instanceof SoukCompassError) {
        return { ...errorResult(err.message) };
      }
      console.error("[souk-compass] Unexpected error:", err);
      return { ...errorResult("An unexpected error occurred") };
    }
  });
  const transport = new StdioServerTransport;
  await server.connect(transport);
}
main().catch(console.error);
